export async function commit(cwd: string, message: string) {
  await git(cwd, 'add', '-A');
  if (await git(cwd, 'status', '--porcelain')) await git(cwd, 'commit', '-m', message);
  return git(cwd, 'rev-parse', 'HEAD');
}
